// =====================================================================
// SCENES
// =====================================================================
function sceneTitle() {
    titleBackground()
    say("THE HONEST ESSAY", "AI, Ethics & You in Belize. Press A to continue.")
    say("Narrator", "AI tools are everywhere in Belize - in phones, homes and schools.")
    say("Narrator", "Meet Maya, a student in Belize City, facing a tempting shortcut.")
}

function sceneClassroom() {
    teacher.setFlag(SpriteFlag.Invisible, false)
    teacher.setPosition(16, 48)
    maya.setPosition(146, 54)
    classroomBoard("History Essay", "Due: FRIDAY")
    teacherSay("Class, write an essay on Belize's independence: 21 September 1981.")
    mayaSay("Miss, can AI just write it for us?")
    teacherSay("AI can help you learn - but passing off AI work as yours is cheating.")
    teacherSay("Start the right way: use real sources!")
}

function level1Research() {
    libraryBackground()
    teacher.setFlag(SpriteFlag.Invisible, true)
    say("LEVEL 1: Research", "Use the arrow keys. Grab blue BOOKS (+1). Avoid white AI essays (-2)!")
    maya.setPosition(80, 80)
    playLevel(1, 35)
    sprites.destroyAllSpritesOfKind(SpriteKind.GoodSource)
    sprites.destroyAllSpritesOfKind(SpriteKind.Shortcut)
}

function sceneNightIntro() {
    nightBackground()
    maya.setPosition(40, 56)
    say("Narrator", "Thursday night in Belmopan. The essay is due tomorrow...")
    mayaSay("AI, write my whole essay for me!")
    createRobot()
    robot.setPosition(118, 50)
    robotSay("Then it wouldn't be YOUR work. I'll help you learn instead.")
    robotSay("Warning: I learned mostly about OTHER countries. I can be biased about Belize.")
}

function level2FactOrBias() {
    say("LEVEL 2: Fact or Bias?", "Read each AI claim. CATCH true facts (+2). DODGE biased claims (-1)!")
    maya.setPosition(80, 100)
    robotPatrol()
    playLevel(2, 40)
    robotStop()
    sprites.destroyAllSpritesOfKind(SpriteKind.Claim)
}

function sceneNightOutro() {
    robotGlitchEffect()
    robotSay("You caught my mistakes! Always check AI with trusted sources.")
    mayaSay("AI is a tool for thinking - not a replacement for it.")
    robot.setFlag(SpriteFlag.Invisible, true)
}

function sceneHallwayIntro() {
    hallwayBackground()
    maya.setPosition(80, 80)
    say("Narrator", "Friday. AI detector drones now scan every student's essay.")
    say("Detector", "NON-STANDARD ENGLISH = SUSPICIOUS. YOU ARE BEING WATCHED.")
    mayaSay("Jaden writes in Kriol style - and they flagged him for cheating!")
    createDrone(10, 30, 30)
    createDrone(150, 30, 34)
    createDrone(150, 110, 38)
    createDrone(10, 110, 42)
    createDrone(80, 25, 46)
}

function level3Rights() {
    say("LEVEL 3: Your Rights", "Dodge the drones! Collect green HUMAN RIGHTS shields (+2).")
    playLevel(3, 35)
    sprites.destroyAllSpritesOfKind(SpriteKind.Right)
    dronesPowerDown()
}

function sceneEnding() {
    teacher.setFlag(SpriteFlag.Invisible, false)
    teacher.setPosition(16, 48)
    maya.setPosition(146, 54)
    classroomBoard("Our Class", "AI Agreement")
    glideDrone(0, 50, 8, 400)
    glideDrone(1, 80, 8, 400)
    glideDrone(2, 110, 8, 400)
    teacherSay("Stop! A detector score is not proof. This one is biased against Kriol.")
    teacherSay("A Human Rights-Based Approach means privacy, dignity and a fair hearing for all.")
    announceRules()
    dronesBecomeHelpers()
    say("Helper drones", "Rebooted as AI Literacy Helpers: here to TEACH, not to watch.")
    mayaSay("Here's my essay - and a note on how I used AI to brainstorm.")
    teacherSay("Excellent, Maya. That's responsible AI use.")
    say("Result", "Integrity points: " + integrity + ". Rating: " + mayaRating())
    say("Narrator", "Use AI to learn, not to replace learning!")
}

// =====================================================================
// MAIN STORY: just call each scene in order
// =====================================================================
setupData()
sceneTitle()
sceneClassroom()
level1Research()
sceneNightIntro()
level2FactOrBias()
sceneNightOutro()
sceneHallwayIntro()
level3Rights()
sceneEnding()
game.gameOver(true)